#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    return (uint64_t)((__uint128_t)a * b % mod);
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = mul_mod(res, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return res;
}

/* deterministic Miller–Rabin for n ≤ 0xBFA17DC6 using bases 2,3,5,7,11,13 */
static int is_prime(uint64_t n)
{
    static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a % n == 0) return 1;          // n equals one of the bases
        if (n % a == 0) return 0;          // divisible by a small base
        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1) continue;
        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) { composite = 0; break; }
            if (x == 1) return 0; // definitely composite
        }
        if (composite) return 0;
    }
    return 1;
}

int main(int argc, char **argv)
{
    const uint64_t MAX_VAL = 0xBFA17DC6ULL; // upper bound used by original binary
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long val = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (val < 0) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    uint64_t n = (uint64_t)val;
    if (n > MAX_VAL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n < 2) {
        puts("NOT_PRIME");
        return 0;
    }
    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
